const names={A:'Workspace',B:'Guided setup',C:'Run monitor'};
const state={module:'payroll',view:'workspace',variant:['A','B','C'].includes(new URLSearchParams(location.search).get('variant'))?new URLSearchParams(location.search).get('variant'):'A',status:'ready',events:[],step:0,elapsed:0,started:null,timer:null,speed:1400,question:true,files:null,template:null,filter:'all',search:'',steer:'',runs:[],context:{payroll:modules.payroll.context,ap:modules.ap.context},instructions:{payroll:modules.payroll.instructions,ap:modules.ap.instructions}};
const m=()=>modules[state.module];
const isBusy=()=>['running','paused','waiting'].includes(state.status);
const statusLabel=()=>({ready:'Ready to run',running:'Agent is working',paused:'Paused',waiting:'Needs your input',completed:'Draft ready',stopped:'Stopped · draft retained'}[state.status]);
const seconds=()=>`${Math.floor(state.elapsed/60)}:${String(state.elapsed%60).padStart(2,'0')}`;
const toolCount=()=>state.events.filter(e=>e.type==='tool').length;
const modelCount=()=>state.events.filter(e=>e.type==='model').length;
const records=()=>state.step>=9||state.status==='completed'?m().records:0;
const formatTime=t=>new Date(t).toLocaleTimeString('en-GB',{hour12:false,hour:'2-digit',minute:'2-digit',second:'2-digit'});
const statusPill=()=>`<span class="status ${state.status==='waiting'?'attention':state.status==='stopped'?'stopped':state.status}"><i class="dot"></i>${statusLabel()}</span>`;
const btn=(action,label,ic,kind='',disabled=false)=>`<button class="btn ${kind}" data-action="${action}" ${disabled?'disabled':''}>${ic?icon(ic):''}${label}</button>`;
const controls=()=>state.status==='running'?`<div class="controls">${btn('pause','Pause','pause','small')}${btn('stop','Stop','stop','small')}</div>`:state.status==='paused'?`<div class="controls">${btn('resume','Resume','play','small')}${btn('stop','Stop','stop','small')}</div>`:state.status==='waiting'?btn('stop','Stop','stop','small'):'';
function sidebar(){return `<aside class="sidebar"><div class="brand"><span class="brandmark"><i></i><i></i><i></i><i></i></span><span>document<small>intelligence</small></span></div><div class="module-block"><select class="module-select" id="module-select" aria-label="Select module"><option value="payroll" ${state.module==='payroll'?'selected':''}>◈ &nbsp; Payroll</option><option value="ap" ${state.module==='ap'?'selected':''}>▤ &nbsp; Accounts payable · preview</option></select></div><nav class="nav" aria-label="Main navigation">${[['workspace','grid','Workspace'],['instructions','sliders','Module instructions'],['history','clock','Run history'],['diagnostics','terminal','Diagnostics']].map(([v,i,t])=>`<button class="${state.view===v?'active':''}" data-view="${v}">${icon(i)}${t}${v==='diagnostics'&&state.events.length?`<small>${state.events.length}</small>`:''}</button>`).join('')}</nav><div class="user"><span class="avatar">LM</span><span>Lily Malaysia</span></div></aside>`;}
function mobileNav(){return `<nav class="mobile-navigation" aria-label="Mobile navigation"><select id="mobile-module-select" aria-label="Select module"><option value="payroll" ${state.module==='payroll'?'selected':''}>Payroll</option><option value="ap" ${state.module==='ap'?'selected':''}>Accounts payable · preview</option></select>${[['workspace','grid','Workspace'],['instructions','sliders','Instructions'],['diagnostics','terminal','Diagnostics'],['history','clock','History']].map(([v,i,t])=>`<button data-view="${v}" class="${state.view===v?'active':''}" aria-label="${t}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;}
function header(){return `<header class="topbar"><span class="mobile-brand">document / intelligence</span><div class="crumb">Workspace ${icon('chevron')} ${esc(m().label)} ${icon('chevron')} <b>${state.view==='workspace'?'Monthly ingestion':{instructions:'Instructions',history:'Run history',diagnostics:'Diagnostics'}[state.view]}</b></div><button class="demo-pill" data-action="demo" aria-label="About this simulated prototype">DEMO ${icon('info')}</button></header>`;}
function heading(){const title={workspace:m().title,instructions:'Instructions',history:'Run history',diagnostics:'Diagnostics'}[state.view];return `<div class="heading"><h1>${title}</h1><div class="heading-right">${state.view==='workspace'?`${statusPill()}${btn('diagnostics','Diagnostics','terminal')}`:btn('workspace','Workspace','arrow')}</div></div>`;}
function stats(){return `<div class="stats">${[['Files',state.files?.length??m().count,'folder'],[state.module==='payroll'?'Employees':'Invoices',records()||'—','layers'],['Tool calls',toolCount(),'terminal'],['Elapsed',seconds(),'clock']].map(([l,v,i])=>`<div class="stat"><div><span>${l}</span><strong>${v}</strong></div>${icon(i)}</div>`).join('')}</div>`;}
function tree(){return state.files?`<div class="filetree">${state.files.slice(0,6).map(f=>`<div class="tree-row">${icon('file')}<span>${esc(f.path)}</span></div>`).join('')}${state.files.length>6?`<div class="tree-row">+ ${state.files.length-6} more files</div>`:''}</div>`:`<div class="filetree"><div class="tree-row">${icon('folder')}<span>${m().folder}/</span></div>${m().files.map(([name,type,n],i)=>`<div class="tree-row indent">${icon(type)}<span>${esc(name)}</span>${n?`<span class="number">${n}</span>`:''}</div>`).join('')}</div>`;}
function inputs(guided=false){return `<section class="panel ${guided?'guided-inputs':''}" aria-label="Run setup"><div class="panel-head"><h2>${icon('folder')} Run inputs</h2></div><div class="panel-body"><div><div class="field"><label for="period">Reporting month</label><input type="month" id="period" value="${m().period}" ${isBusy()?'disabled':''}></div><div class="field"><label>Source documents <small>${state.files?'Local selection':'Sample packet'}</small></label><button class="dropzone" data-action="folder" ${isBusy()?'disabled':''}>${icon('folder')}<strong>${state.files?'Change folder':'Choose folder'}</strong></button>${tree()}<button class="context-link" data-action="files">Files ${icon('chevron')}</button></div></div><div><div class="field"><label>Output template</label><button class="template-file" data-action="template" ${isBusy()?'disabled':''}><span class="file-icon">XLS</span><span><strong>${esc(state.template?.name??m().template)}</strong><small>${state.template?'Selected':`${m().sheets} tabs`}</small></span>${icon('chevron')}</button></div><div class="field"><label for="run-instructions">Run instructions</label><textarea id="run-instructions" placeholder="Add instructions…">${esc(state.instructions[state.module])}</textarea></div><button class="context-link" data-action="instructions">${icon('sliders')} Module context ${icon('chevron')}</button></div></div><div class="inputs-footer">${btn('run',state.events.length?'Run again':'Run agent','spark','primary',isBusy())}</div></section>`;}
function question(){return state.status==='waiting'?`<div class="question-box"><strong>Which period should this allowance use?</strong><p>EMP-024: effective in June; included in the October packet.</p><div class="question-actions">${btn('exclude','Leave out of October',null,'small')}${btn('include','Include this month',null,'small')}</div></div>`:'';}
function eventMarkup(e){return `<div class="event ${e.level==='WARN'?'warn':''} ${e.type==='user'?'user':''}"><div class="event-icon">${icon(e.level==='WARN'?'warning':e.type==='model'?'spark':e.type==='user'?'chat':'check')}</div><div><div class="event-heading"><button class="event-title" data-event="${e.id}">${esc(e.title)}</button><time>${formatTime(e.timestamp)}</time></div>${e.level==='WARN'||e.type==='user'?`<p>${esc(e.message)}</p>`:''}</div></div>`;}
function activity(){return `<section class="panel activity"><div class="panel-head"><h2>${icon('spark')} Activity</h2>${controls()||`<span class="label">${state.events.length?state.events[0].run_id:''}</span>`}</div><div class="progress-track"><i style="width:${Math.round(state.step/m().events.length*100)}%"></i></div><div class="activity-body" id="activity-scroll" role="log" aria-label="Agent activity" aria-live="polite">${state.events.length?state.events.map(eventMarkup).join(''):`<div class="quiet-empty"><div class="agent-logo">${icon('spark')}</div><p>Start a run to see activity.</p></div>`}${question()}</div><div class="activity-footer"><form class="steer" id="steer-form"><input id="steer-input" aria-label="Message the agent" placeholder="Message the agent…" value="${esc(state.steer)}"><button type="submit" aria-label="Send instruction">${icon('up')}</button></form></div></section>`;}
function outputs(){return `<section class="panel"><div class="panel-head"><h2>${icon('file')} Output</h2></div><div class="panel-body"><p class="artifact-title">${state.module==='payroll'?'Central depository':'Invoice upload'}</p><div class="artifact-meta">${m().sheets} tabs</div><button class="artifact-preview" style="width:100%" data-action="preview" aria-label="Open sample output preview"><table class="mini-sheet" aria-hidden="true"><tr><td>ID</td><td>Name</td><td>Effective</td><td>Amount</td></tr><tr><td>001</td><td>A. Tan</td><td>01 Oct</td><td>6,200</td></tr><tr><td>002</td><td>S. Lee</td><td>01 Oct</td><td>5,800</td></tr><tr><td>003</td><td>M. Ali</td><td>14 Oct</td><td>4,500</td></tr></table></button>${btn('preview','Sample preview','arrow','artifact-download')}${btn('csv','Sample CSV','down','ghost artifact-download',state.status!=='completed')}</div></section>`;}
function session(){return `<section class="panel session"><div class="panel-head"><h2>${icon('chart')} Run details</h2></div><div class="panel-body">${[['Model calls',String(modelCount()).padStart(2,'0')],['Context',state.events.some(e=>e.type==='context')?'29% · compacted':'18%'],['Warnings',state.events.filter(e=>e.level==='WARN'&&e.type!=='question').length]].map(([k,v])=>`<div class="session-row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}${btn('diagnostics','Diagnostics','terminal')}</div></section>`;}
function right(){return `<aside class="right-stack">${outputs()}${session()}</aside>`;}
function VariantA(){return `<div class="workspace-grid">${inputs()}${activity()}${right()}</div>`;}
function VariantB(){return `<div class="guided-layout"><div class="guided-top"><section class="panel guided-intro"><h2>Module context</h2><div class="field"><label for="module-context" class="sr-only">${esc(m().label)} module context</label><textarea id="module-context">${esc(state.context[state.module])}</textarea></div>${btn('save-context','Apply','check','small')}</section>${inputs(true)}</div><div class="guided-bottom">${activity()}${right()}</div></div>`;}
function diagnosticPanel(){const events=state.events.filter(e=>(state.filter==='all'||e.type===state.filter||state.filter==='warnings'&&e.level==='WARN')&&`${e.name} ${e.title} ${e.message}`.toLowerCase().includes(state.search.toLowerCase()));return `<section class="panel"><div class="panel-head"><h2>${icon('terminal')} Execution trace</h2>${btn('export','Export JSONL','down','small',!state.events.length)}</div><div class="diagnostic-toolbar"><div class="filter-buttons" role="group" aria-label="Filter trace events">${[['all','All'],['model','Model'],['tool','Tools'],['warnings','Warnings']].map(([f,t])=>`<button class="${state.filter===f?'active':''}" data-filter="${f}">${t}</button>`).join('')}</div><input id="log-search" type="search" placeholder="Search events…" aria-label="Search diagnostic events" value="${esc(state.search)}"></div><div style="overflow:auto"><table class="trace-table"><thead><tr><th class="mobile-hide">Time</th><th>Event / operation</th><th>Status</th><th class="hide-small">Duration</th><th class="hide-small">Tokens</th><th class="mobile-hide">Trace</th></tr></thead><tbody>${events.map(e=>`<tr data-event="${e.id}" tabindex="0" role="button" aria-label="Inspect ${esc(e.name)}"><td class="mono mobile-hide">${formatTime(e.timestamp)}</td><td class="trace-name">${esc(e.name)}<div style="font-size:9px;color:#96a087;font-weight:400;margin-top:4px">${esc(e.title)}</div></td><td><span class="loglevel ${e.level==='WARN'?'warn':''}">${e.level==='WARN'?'WARN':'OK'}</span></td><td class="mono hide-small">${e.duration_ms} ms</td><td class="mono hide-small">${e.usage?e.usage.input_tokens+' / '+e.usage.output_tokens:'—'}</td><td class="mono mobile-hide">${e.span_id.slice(-6)}</td></tr>`).join('')}</tbody></table>${!events.length?`<div class="empty-state">${icon('terminal')}${state.events.length?'No matching events.':'No events yet.'}</div>`:''}</div></section>`;}
function VariantC(){return `<div class="ops-input-summary"><span><strong>${esc(state.files?'Selected folder':m().folder+'/')}</strong> &nbsp; · &nbsp; ${state.files?.length??m().count} files &nbsp; · &nbsp; ${esc(state.template?.name??m().template)}</span><div class="controls">${controls()}${btn('setup','Edit inputs','sliders','small',isBusy())}${btn('run','Run agent','play','primary small',isBusy())}</div></div><div class="ops-layout"><div>${diagnosticPanel()}${session()}</div>${activity()}</div>`;}
function instructionsPage(){return `<div class="page-panel"><div class="instructions-grid"><section class="panel instruction-card"><h3>Module context</h3><div class="field"><label for="module-context" class="sr-only">Reusable module instructions</label><textarea id="module-context">${esc(state.context[state.module])}</textarea></div><div class="instruction-foot">${btn('save-context','Apply','check','lime')}</div></section><section class="panel instruction-card"><h3>This run</h3><div class="field"><label for="run-instructions" class="sr-only">Run instructions</label><textarea id="run-instructions">${esc(state.instructions[state.module])}</textarea></div><div class="instruction-foot">${btn('workspace','Done','check')}</div></section></div></div>`;}
function historyPage(){return `<section class="panel page-panel"><div class="panel-head"><h2>${icon('clock')} Runs</h2></div>${state.runs.length?state.runs.map(r=>`<div class="history-row"><div>${esc(r.title)}<small class="mono">${r.id} · ${formatTime(r.created)}</small></div><span class="status ${r.status==='waiting'?'attention':''}">${esc(r.status)}</span><span>${r.events.length} events</span><button class="btn small" data-run="${r.id}">Export logs</button></div>`).join(''):`<div class="empty-state">${icon('clock')}No runs yet.</div>`}</section>`;}
function switcher(){return `<div class="variant-switcher" aria-label="Prototype layout selector"><button data-action="prev-variant" aria-label="Previous layout">${icon('left')}</button><span><small>LAYOUT ${state.variant}</small> &nbsp; ${names[state.variant]}</span><button data-action="next-variant" aria-label="Next layout">${icon('chevron')}</button></div>`;}
function render(){document.title=m().label+' workspace · Document Intelligence';const focus=document.activeElement;const field=focus?.id;const cursor=focus?.selectionStart;const scroll=$('#activity-scroll')?.scrollTop??0;$('#app').innerHTML=`<div class="shell">${sidebar()}<main class="main">${header()}${mobileNav()}<div class="content">${heading()}${state.view==='workspace'?stats()+({A:VariantA,B:VariantB,C:VariantC}[state.variant])():state.view==='instructions'?instructionsPage():state.view==='history'?historyPage():`${stats()}${diagnosticPanel()}`}<details class="variant-state"><summary>Preview state</summary><code>module: ${state.module} · view: ${state.view} · run: ${state.status} · events: ${state.events.length} · memory: browser session</code></details></div></main></div>${switcher()}`;if(field&&$('#'+field)){const el=$('#'+field);el.focus();if(typeof cursor==='number'&&el.setSelectionRange&&el.type!=='month')el.setSelectionRange(cursor,cursor);}if($('#activity-scroll'))$('#activity-scroll').scrollTop=scroll;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function dialog(title,html){$('#details').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button data-action="close-dialog" aria-label="Close dialog">×</button></div>${html}`;if(!$('#details').open)$('#details').showModal();}
function updateRun(){const r=state.runs.find(r=>r.id===state.runId);if(r){r.status=state.status;r.events=[...state.events];}}
function emit(type,title,message,name,args={},result=null,level='INFO'){const e={id:'evt-'+(state.events.length+1),run_id:state.runId||'preview',trace_id:state.traceId||'trace-preview',span_id:'span-'+String(state.events.length+1).padStart(6,'0'),parent_span_id:'span-run',timestamp:new Date().toISOString(),module:state.module,type,level,title,message,name,duration_ms:type==='model'?1260:type==='tool'?180:8,arguments:args,result,simulated:true};if(type==='model')e.usage={input_tokens:2460,output_tokens:380,estimated_cost_usd:null};state.events.push(e);updateRun();render();$('#activity-scroll')?.scrollTo({top:$('#activity-scroll').scrollHeight,behavior:'smooth'});return e;}
function tick(){if(state.status!=='running')return;state.elapsed=Math.floor((Date.now()-state.started)/1000);const item=m().events[state.step];if(!item){finish();return;}state.step++;emit(...item);if(item[0]==='question'&&state.question){state.status='waiting';clearInterval(state.timer);updateRun();render();$('#activity-scroll')?.scrollTo({top:$('#activity-scroll').scrollHeight});}else if(item[0]==='job'&&item[3]==='job.complete')finish();}
function start(){if(isBusy())return;if($('#details').open)$('#details').close();state.status='running';state.step=0;state.elapsed=0;state.events=[];state.started=Date.now();state.runId='run-'+String(state.runs.length+1).padStart(3,'0');state.traceId='trace-'+crypto.randomUUID();state.view='workspace';state.runs.unshift({id:state.runId,title:m().title,created:Date.now(),status:'running',events:[]});render();$('.activity')?.scrollIntoView({behavior:'smooth',block:'nearest'});if(state.files||state.template)toast('Demo mode: selected filenames are displayed; the run still uses synthetic sample events.');tick();state.timer=setInterval(tick,state.speed);}
function resume(){state.status='running';state.started=Date.now()-state.elapsed*1000;updateRun();render();clearInterval(state.timer);state.timer=setInterval(tick,state.speed);}
function finish(){clearInterval(state.timer);state.status='completed';state.elapsed=Math.floor((Date.now()-state.started)/1000);updateRun();render();toast('Sample run complete.');}
function answer(include){emit('user',include?'Included the allowance for October':'Left the allowance out of October','Recorded your decision and continued with the remaining draft.','user.answer',{record:'EMP-024',include_in_period:include},{decision_saved:true});resume();}
function download(name,data,mime='text/plain'){const url=URL.createObjectURL(new Blob([data],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportEvents(events=state.events,id=state.runId){download((id||'preview')+'-events.jsonl',events.map(e=>JSON.stringify(e)).join('\n')+'\n','application/x-ndjson');}
function outputPreview(){const rows=state.module==='payroll'?[['EMP-001','Amira Tan','New Joiner','2026-10-01','6200.00'],['EMP-002','Sam Lee','Employee Change','2026-10-01','5800.00'],['EMP-003','Mika Ali','One-time Payment','2026-10-14','450.00']]:[['SUP-001','Sample Supplies','INV-001','2026-10-01','2400.00'],['SUP-002','Sample Services','INV-002','2026-10-01','1800.00']];return rows;}
function preview(){dialog('Sample destination preview',`<p>Sample rows · no workbook generated.</p><div class="preview-table-wrap"><table class="preview-table"><thead><tr>${['Identifier','Name',state.module==='payroll'?'Section':'Invoice','Effective date','Amount (MYR)'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${outputPreview().map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);}
function changeVariant(delta){const keys=['A','B','C'];state.variant=keys[(keys.indexOf(state.variant)+delta+3)%3];const url=new URL(location.href);url.searchParams.set('variant',state.variant);history.replaceState(null,'',url);render();}
function saveFields(){if($('#run-instructions'))state.instructions[state.module]=$('#run-instructions').value;if($('#module-context'))state.context[state.module]=$('#module-context').value;}
const actions={demo:()=>dialog('About this demo',`<p>Scripted events and sample output. Selected files stay in your browser; their contents are not processed. Context and history reset on reload.</p><p>Event details and token counts are simulated. Diagnostics expose tool data and summaries, not private model reasoning.</p>`),workspace:()=>{saveFields();state.view='workspace';render();},instructions:()=>{saveFields();state.view='instructions';render();},diagnostics:()=>{saveFields();state.view='diagnostics';render();},folder:()=>$('#folder-picker').click(),template:()=>$('#template-picker').click(),files:()=>dialog('Source file inventory',`<p>${state.files?'Selected filenames':'Sample files'}</p><div class="file-list">${state.files?state.files.map(f=>esc(f.path)+' · '+f.size+' bytes').join('<br>'):m().files.map(([f,t,n])=>`${t==='folder'?'▸':'&nbsp; └'} ${esc(f)} ${esc(n)}`).join('<br>')}</div>`),run:()=>{saveFields();start();},pause:()=>{clearInterval(state.timer);state.status='paused';emit('job','Run paused','The draft and tool results are retained in this browser session.','job.pause');},resume,stop:()=>{clearInterval(state.timer);state.status='stopped';emit('job','Run stopped','Retained existing events and the illustrative preview. Start another sample run whenever ready.','job.stop');},exclude:()=>answer(false),include:()=>answer(true),preview,csv:()=>download((state.module==='payroll'?'Payroll':'AP')+'_sample_preview.csv','Identifier,Name,Section,Effective Date,Amount MYR\n'+outputPreview().map(r=>r.join(',')).join('\n')+'\n','text/csv'),export:()=>exportEvents(),'prev-variant':()=>changeVariant(-1),'next-variant':()=>changeVariant(1),'close-dialog':()=>$('#details').close(),'save-context':()=>{saveFields();toast('Context applied for the next run.');},setup:()=>dialog('Run setup',`<div class="setup-drawer">${inputs()}</div>`)};
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action&&!action.disabled){actions[action.dataset.action]?.();return;}const view=e.target.closest('[data-view]');if(view){saveFields();state.view=view.dataset.view;render();return;}const event=e.target.closest('[data-event]');if(event){const record=state.events.find(x=>x.id===event.dataset.event);if(record)dialog(record.title,`<p>Simulated event</p><pre>${esc(JSON.stringify(record,null,2))}</pre>`);return;}const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return;}const run=e.target.closest('[data-run]');if(run){const record=state.runs.find(r=>r.id===run.dataset.run);exportEvents(record.events,record.id);}});
document.addEventListener('input',e=>{if(e.target.id==='run-instructions')state.instructions[state.module]=e.target.value;if(e.target.id==='module-context')state.context[state.module]=e.target.value;if(e.target.id==='steer-input')state.steer=e.target.value;if(e.target.id==='log-search'){state.search=e.target.value;render();}});
document.addEventListener('change',e=>{if(e.target.id==='module-select'||e.target.id==='mobile-module-select'){if(isBusy()){e.target.value=state.module;toast('Stop this run before switching modules.');return;}saveFields();state.module=e.target.value;state.status='ready';state.events=[];state.step=0;state.elapsed=0;state.files=null;state.template=null;state.view='workspace';render();}if(e.target.id==='period'){m().period=e.target.value;toast('Reporting month updated. Demo events still illustrate October 2026.');}});
document.addEventListener('submit',e=>{if(e.target.id!=='steer-form')return;e.preventDefault();const msg=state.steer.trim();if(!msg)return;if(!isBusy()){toast('Start a sample run first to send an instruction.');return;}state.steer='';state.instructions[state.module]+='\n'+msg;emit('user','New instruction received',msg,'user.instruction',{instruction:msg},{applied_to:'current run',simulation:'Recorded only; sample events are scripted.'});toast('Instruction recorded · scripted demo.');});
$('#folder-picker').addEventListener('change',e=>{if(!e.target.files.length)return;state.files=[...e.target.files].map(f=>({path:f.webkitRelativePath||f.name,size:f.size}));render();toast('Folder selected locally. No contents read or uploaded.');});
$('#template-picker').addEventListener('change',e=>{if(!e.target.files.length)return;state.template={name:e.target.files[0].name,size:e.target.files[0].size};render();toast('Template filename selected. No workbook contents read.');});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-event]'))e.target.click();if(['ArrowLeft','ArrowRight'].includes(e.key)&&!e.target.closest('input,textarea,select,[contenteditable],dialog')){e.preventDefault();changeVariant(e.key==='ArrowRight'?1:-1);}});
$('#details').addEventListener('click',e=>{if(e.target===$('#details'))$('#details').close();});
window.addEventListener('popstate',()=>{state.variant=new URLSearchParams(location.search).get('variant')||'A';if(!names[state.variant])state.variant='A';render();});
render();
